#include <bits/stdc++.h>
using namespace std;
int M,N;
vector<string> grid;

void doFill(int x,int y,char c){
    char orig = grid[y-1][x-1];
    if(orig==c) return;
    queue<pair<int,int>> q;
    q.push({x,y});
    grid[y-1][x-1]=c;
    int dx[4]={1,-1,0,0}, dy[4]={0,0,1,-1};
    while(!q.empty()){
        auto pr=q.front(); q.pop();
        int cx=pr.first, cy=pr.second;
        for(int d=0;d<4;d++){
            int nx=cx+dx[d], ny=cy+dy[d];
            if(nx<1||nx>M||ny<1||ny>N) continue;
            if(grid[ny-1][nx-1]==orig){
                grid[ny-1][nx-1]=c;
                q.push({nx,ny});
            }
        }
    }
}

int main(){
    string line;
    while(getline(cin,line)){
        if(line.empty()) continue;
        char cmd = line[0];
        istringstream iss(line.substr(1));
        if(cmd=='I'){
            iss>>M>>N;
            grid.assign(N, string(M,'O'));
        } else if(cmd=='C'){
            grid.assign(N, string(M,'O'));
        } else if(cmd=='L'){
            int x,y; char c; iss>>x>>y>>c;
            if(x<1||x>M||y<1||y>N) continue;
            grid[y-1][x-1]=c;
        } else if(cmd=='V'){
            int x,y1,y2; char c; iss>>x>>y1>>y2>>c;
            if(y1>y2) swap(y1,y2);
            if(x<1||x>M) continue;
            y1=max(y1,1); y2=min(y2,N);
            for(int y=y1;y<=y2;y++) grid[y-1][x-1]=c;
        } else if(cmd=='H'){
            int x1,x2,y; char c; iss>>x1>>x2>>y>>c;
            if(x1>x2) swap(x1,x2);
            if(y<1||y>N) continue;
            x1=max(x1,1); x2=min(x2,M);
            for(int x=x1;x<=x2;x++) grid[y-1][x-1]=c;
        } else if(cmd=='K'){
            int x1,y1,x2,y2; char c; iss>>x1>>y1>>x2>>y2>>c;
            if(x1>x2) swap(x1,x2);
            if(y1>y2) swap(y1,y2);
            x1=max(x1,1); x2=min(x2,M); y1=max(y1,1); y2=min(y2,N);
            for(int y=y1;y<=y2;y++) for(int x=x1;x<=x2;x++) grid[y-1][x-1]=c;
        } else if(cmd=='F'){
            int x,y; char c; iss>>x>>y>>c;
            if(x<1||x>M||y<1||y>N) continue;
            doFill(x,y,c);
        } else if(cmd=='S'){
            string name; iss>>name;
            cout<<name<<"\n";
            for(int y=0;y<N;y++) cout<<grid[y]<<"\n";
        } else if(cmd=='X'){
            break;
        }
    }
}

